contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take inputs to call SetMinSum and SetLogFile with arbitrary values.
    // The test will call them (catching reverts) and then assert that if they did not revert,
    // then Initialized() was not implicitly set by those calls (i.e., intitalized must remain false).
    // We can only observe via public surface: MinSum getter and LogFile address, and we cannot read intitalized directly.
    // So the invariant we assert is: if SetMinSum/SetLogFile did not revert then calling Initialized() afterwards must still succeed
    // (i.e., Initialized was not already set). We implement this by attempting Initialized() and seeing if it reverts.

    function run(uint newMin, address newLog) public payable {
        // No preconditions on params
        // First, call SetMinSum and SetLogFile, catching reverts.
        bool revertMin;
        bool revertLog;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertMin = true;
        } else {
            revertMin = false;
        }

        c.SetLogFile(newLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertLog = true;
        } else {
            revertLog = false;
        }

        // Now attempt to call Initialized(); if either prior call did not revert it should still be possible
        // to call Initialized() (i.e., it should not revert because intitalized should currently be false).
        bool initReverted;
        c.Initialized(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        // General rule: if SetMinSum did not revert OR SetLogFile did not revert, then Initialized() must NOT have reverted here.
        // (This captures that the two setter functions cannot themselves set intitalized to true or cause it to be set.)
        assert(!( !revertMin && initReverted) && !( !revertLog && initReverted));
    }

    // accept Ether if needed by calls (none used here), keep receive to satisfy potential refunds
    receive() external payable {}
}

