// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMin, address newLog) internal {
        bool revertMin;
        bool revertLog;
        try c.SetMinSum(newMin) {
            revertMin = false;
        } catch {
            revertMin = true;
        }
        try c.SetLogFile(newLog) {
            revertLog = false;
        } catch {
            revertLog = true;
        }
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        assertTrue(!( !revertMin && initReverted) && !( !revertLog && initReverted));
    }

    function testFuzz_run(uint256 newMin, address newLog) public {
        vm.assume(newLog.code.length == 0 && uint160(newLog) > 0xffff && newLog != address(this) && newLog != address(c) && newLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newLog != 0x000000000000000000636F6e736F6c652e6c6f67 && newLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newMin, newLog);
    }

    receive() external payable {}
}
